# 守る: Scripts/build-scape-exe.ps1
$upTo = 'S4b2'
# （作る物・直す物は変数で指す）
$scripts = 'Scripts'; $builds = 'Builds'; $manualDir = 'Docs/Guides/Manuals/kaedescape'
# 「守る」に書いた #G のテストが git にあるか（無いと何も言わずに守られなくなる。確認コマンドは -Command で回るので自分のファイルは読めない）
foreach ($n in 'EditMode/ViewModeStateTests', 'EditMode/OrbitCameraModelTests', 'EditMode/CameraCollisionTests', 'EditMode/MmoWalkTests', 'EditMode/FineAdjustModelTests', 'EditMode/CursorPolicyTests', 'EditMode/ViewKeyMapTests', 'PlayMode/ThirdPersonTests', 'PlayMode/ThirdPersonCameraWallTests', 'PlayMode/ViewSwitchTests', 'PlayMode/FirstPersonShotTests', 'PlayMode/AutoShotFirstPersonTests') {
    if (-not (git ls-files -- "Assets/Tests/$n.cs")) { Write-Host "git に無い（#G のテスト・守れない）: Assets/Tests/$n.cs"; exit 1 }
}
pwsh -NoProfile -File Scripts/unity-test.ps1 -Platform All -Filter 'KaedeScapeBuii.Tests'
if ($LASTEXITCODE) { Write-Host 'テストが通らない'; exit 1 }
$m1doc = Get-Content Docs/Guides/Working/scape-m1-detailed-design.md -Raw -Encoding utf8
$s4doc = Get-Content Docs/Guides/Working/scape-s4b-detailed-design.md -Raw -Encoding utf8
$m1 = @([regex]::Matches($m1doc, '(?m)^\| `(KaedeScapeBuii\.Tests\.(?:EditMode|PlayMode)\.\w+\.\w+)` \| (?:S1|S2|S4|S6a|S6b) \|') | ForEach-Object { $_.Groups[1].Value })
if ($m1.Count -ne 54) { Write-Host "M1 設計書 9 章のテストの行が $($m1.Count) 個（54 個のはず）"; exit 1 }
$order = @('S4b1', 'S4b2')
$rows = @([regex]::Matches($s4doc, '(?m)^\| `(KaedeScapeBuii\.Tests\.(?:EditMode|PlayMode)\.\w+\.\w+)` \| (S4b1|S4b2) \| (新規|変える) \|'))
if ($rows.Count -ne 48) { Write-Host "S4b 設計書 11 章のテストの行が $($rows.Count) 個（48 個のはず）"; exit 1 }
$changed = @($rows | Where-Object { $_.Groups[3].Value -eq '変える' } | ForEach-Object { $_.Groups[1].Value })
if ($changed.Count -ne 3 -or @($changed | Where-Object { $m1 -notcontains $_ }).Count) { Write-Host '「変える」の行が M1 の 3 本でない'; exit 1 }
$need = @($m1 | Where-Object { $changed -notcontains $_ }) + @($rows | Where-Object { $order.IndexOf($_.Groups[2].Value) -le $order.IndexOf($upTo) } | ForEach-Object { $_.Groups[1].Value })
$x = Get-ChildItem Logs/UnityTest -Directory | Sort-Object Name | Select-Object -Last 1
$xml = @{}
foreach ($p in 'EditMode', 'PlayMode') {
    $f = Join-Path $x.FullName "$p-results.xml"
    if (-not (Test-Path $f)) { Write-Host "結果の XML が無い: $f"; exit 1 }
    $xml[$p] = [xml](Get-Content $f -Raw -Encoding utf8)
}
function Get-Cases([string]$plat, [string]$n) { @($xml[$plat].SelectNodes("//test-case[@fullname='$n' or starts-with(@fullname,'$n(')]")) }
foreach ($n in $need) {
    $plat = $n.Split('.')[2]
    $hit = @(Get-Cases $plat $n)
    if (-not $hit.Count) { Write-Host "テストが無い: $n"; exit 1 }
    if (@($hit | Where-Object { $_.result -ne 'Passed' }).Count) { Write-Host "通っていない: $n"; exit 1 }
}
$smoke = @(Get-Cases 'EditMode' 'KaedeScapeBuii.Tests.SmokeTests.TestRunnerWorks')
if (-not $smoke.Count -or $smoke[0].result -ne 'Passed') { Write-Host 'SmokeTests が通っていない'; exit 1 }
$cases = [ordered]@{
    'EditMode|FocalLengthTableTests.HorizontalFovMatchesBasicDesignTable' = 5
    'PlayMode|ShotCaptureTests.PngSizeMatchesResolution'                 = 3
    'PlayMode|TestWorldWalkTests.ForwardOneSecondMovesAtLeastOneMeter'  = 2
    'PlayMode|TestWorldShotTests.ThreeResolutionsInEachWorld'           = 2
}
foreach ($k in $cases.Keys) {
    $plat, $m = $k -split '\|'
    $c = @(Get-Cases $plat "KaedeScapeBuii.Tests.$plat.$m").Count
    if ($c -lt $cases[$k]) { Write-Host "${m} の場合が $c 個（$($cases[$k]) 個のはず）"; exit 1 }
}
Write-Host "テストの名前 OK: $($need.Count) 本（M1 の変えない 51 ＋ S4b の〜$upTo）＋ SmokeTests"
# S4b-11: 説明書の操作の章
$man = Get-Content "$manualDir/kaedescape-user-manual.md" -Raw -Encoding utf8
foreach ($w in '右ボタン', 'ホイール', '**V**', '**Q**', 'Ctrl', '画像を保存しました', '保存できませんでした') { if (-not $man.Contains($w)) { Write-Host "説明書に「$w」が無い"; exit 1 } }
if ($man.Contains('カーソルが画面の中に固定されて見えなくなります')) { Write-Host '説明書に古いカーソルの説明が残っている'; exit 1 }
# M1-6: 書き出し
$out = pwsh -NoProfile -File "$scripts/build-scape-exe.ps1" -Id test-outdoor,test-indoor
$code = $LASTEXITCODE
$out | Select-Object -Last 5 | ForEach-Object { Write-Host $_ }
if ($code -ne 0 -or -not (($out | Select-Object -Last 1) -match '^Result: PASS')) { Write-Host "書き出しが PASS でない（exit $code）"; exit 1 }
# M1-7・S4b-8・S4b-10: EXE を -scape-autoshot で起動し、ログの 2 行と 3 枚の大きさを見る
function Get-PngSize([string]$p) {
    $b = [System.IO.File]::ReadAllBytes($p)
    if ($b.Length -lt 24 -or [System.Text.Encoding]::ASCII.GetString($b, 1, 3) -ne 'PNG') { return $null }
    $w = ([int]$b[16] -shl 24) -bor ([int]$b[17] -shl 16) -bor ([int]$b[18] -shl 8) -bor [int]$b[19]
    $h = ([int]$b[20] -shl 24) -bor ([int]$b[21] -shl 16) -bor ([int]$b[22] -shl 8) -bor [int]$b[23]
    return "${w}x${h}"
}
foreach ($id in 'test-outdoor', 'test-indoor') {
    $exe = Join-Path $builds "$id/$id.exe"
    if (-not (Test-Path $exe)) { Write-Host "EXE が無い: $exe"; exit 1 }
    $shots = Join-Path $builds "$id/Shots"
    $log = Join-Path $env:TEMP "kaede-autoshot-$id-$(Get-Random).log"
    $start = Get-Date
    $p = Start-Process -FilePath (Resolve-Path $exe) -ArgumentList "-batchmode -scape-autoshot -logFile `"$log`"" -PassThru
    if (-not $p.WaitForExit(180000)) { $p.Kill(); Write-Host "${id}: 3 分で終わらない"; exit 1 }
    if ($p.ExitCode -ne 0) { Write-Host "${id}: 終了コード $($p.ExitCode)"; Get-Content $log -Tail 20 | ForEach-Object { Write-Host "  | $_" }; exit 1 }
    foreach ($pat in 'SCAPE-INPUT actions=InputSystem_Actions', 'SCAPE-VIEW mode=FirstPerson avatarHidden=True', 'SCAPE-FONT glyphs=ok') {
        if (-not (Select-String -Path $log -Pattern $pat -Quiet)) { Write-Host "${id}: EXE のログに「$pat」が無い（設計書 6.3・8.2）"; exit 1 }
    }
    $result = Join-Path $shots 'autoshot-result.json'
    if (-not (Test-Path $result) -or (Get-Item $result).LastWriteTime -lt $start) { Write-Host "${id}: 今回の autoshot-result.json が無い"; exit 1 }
    if ((Get-Content $result -Raw -Encoding utf8 | ConvertFrom-Json).result -ne 'PASS') { Write-Host "${id}: autoshot-result.json の result が PASS でない"; exit 1 }
    foreach ($res in @(@('FullHD', '1920x1080'), @('2K', '2560x1440'), @('4K', '3840x2160'))) {
        $png = @(Get-ChildItem $shots -Filter "${id}_*_35mm_$($res[0]).png" | Where-Object { $_.LastWriteTime -ge $start })
        if ($png.Count -ne 1) { Write-Host "${id}: 今回撮った $($res[0]) の PNG が $($png.Count) 枚"; exit 1 }
        $size = Get-PngSize $png[0].FullName
        if ($size -ne $res[1]) { Write-Host "${id}: $($res[0]) の大きさが $size（$($res[1])）"; exit 1 }
        if (-not (Test-Path ([System.IO.Path]::ChangeExtension($png[0].FullName, '.json')))) { Write-Host "${id}: $($png[0].Name) と同じ名前の JSON が無い"; exit 1 }
    }
    Write-Host "${id}: 一人称で 3 枚 OK・日本語の字 OK（$shots）"
}
if (git status --porcelain -- Packages ProjectSettings) { Write-Host 'Packages・ProjectSettings が変わった'; exit 1 }
exit 0
